CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,name TEXT UNIQUE NOT NULL,password TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'student');
CREATE TABLE IF NOT EXISTS resources(id INTEGER PRIMARY KEY,title TEXT NOT NULL,subject TEXT NOT NULL,category TEXT NOT NULL,semester TEXT NOT NULL,description TEXT,filename TEXT NOT NULL,original TEXT NOT NULL,user_id INTEGER REFERENCES users(id),status TEXT DEFAULT 'pending',views INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS ratings(resource_id INTEGER REFERENCES resources(id),user_id INTEGER REFERENCES users(id),stars INTEGER CHECK(stars BETWEEN 1 AND 5),PRIMARY KEY(resource_id,user_id));
CREATE TABLE IF NOT EXISTS comments(id INTEGER PRIMARY KEY,resource_id INTEGER REFERENCES resources(id),user_id INTEGER REFERENCES users(id),body TEXT NOT NULL,created TEXT DEFAULT CURRENT_TIMESTAMP);
